import React, { useEffect, useState } from 'react';
import api from '../api/axios';

const Formation = () => {
    const [trainings, setTrainings] = useState([]);
    const [trainers, setTrainers] = useState([]);
    const [participants, setParticipants] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [showParticipantModal, setShowParticipantModal] = useState(false);
    const [selectedTraining, setSelectedTraining] = useState(null);
    const [selectedParticipants, setSelectedParticipants] = useState([]);
    const [formData, setFormData] = useState({
        title: '',
        theme: '',
        location: '',
        startDate: '',
        endDate: '',
        trainer: { id: 1 },
        participants: []
    });

    useEffect(() => {
        fetchTrainings();
        fetchTrainers();
        fetchParticipants();
    }, []);

    const fetchTrainings = async () => {
        try {
            const response = await api.get('/rh/trainings');
            setTrainings(response.data);
        } catch (error) {
            console.error('Error fetching trainings:', error);
        }
    };

    const fetchTrainers = async () => {
        try {
            const response = await api.get('/auth/users/formateurs');
            setTrainers(response.data);
        } catch (error) {
            console.error('Error fetching trainers:', error);
        }
    };

    const fetchParticipants = async () => {
        try {
            const response = await api.get('/auth/users/participants');
            setParticipants(response.data);
        } catch (error) {
            console.error('Error fetching participants:', error);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await api.post('/rh/trainings', formData);
            setShowModal(false);
            setFormData({
                title: '',
                theme: '',
                location: '',
                startDate: '',
                endDate: '',
                trainer: { id: 1 },
                participants: []
            });
            fetchTrainings();
        } catch (error) {
            console.error('Error creating training:', error);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        if (name === 'trainer') {
            setFormData(prev => ({
                ...prev,
                trainer: { id: parseInt(value) }
            }));
        } else {
            setFormData(prev => ({
                ...prev,
                [name]: value
            }));
        }
    };

    const handleAddParticipant = (training) => {
        setSelectedTraining(training);
        setSelectedParticipants([]);
        setShowParticipantModal(true);
    };

    const handleParticipantSubmit = async (e) => {
        e.preventDefault();

        try {
            await api.post(`/training/${selectedTraining.id}/participants`, selectedParticipants);
            setShowParticipantModal(false);
            setSelectedTraining(null);
            setSelectedParticipants([]);
            fetchTrainings();
        } catch (error) {
            console.error('Error adding participants:', error);
        }
    };

    const handleParticipantChange = (participantId) => {
        setSelectedParticipants(prev => {
            if (prev.includes(participantId)) {
                return prev.filter(id => id !== participantId);
            } else {
                return [...prev, participantId];
            }
        });
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-100 p-6">
            <div className="max-w-7xl mx-auto">
                {/* Header Section */}
                <div className="mb-10">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                        <div>
                            <h1 className="text-4xl font-bold bg-gradient-to-r from-slate-800 to-slate-600 bg-clip-text text-transparent mb-2">
                                Gestion des Formations
                            </h1>
                            <p className="text-slate-600">Organisez et suivez vos programmes de formation</p>
                        </div>
                        <button
                            onClick={() => setShowModal(true)}
                            className="group relative bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-8 py-4 rounded-xl font-semibold shadow-lg hover:shadow-xl transform hover:-translate-y-1 transition-all duration-300 flex items-center overflow-hidden"
                        >
                            <div className="absolute inset-0 bg-gradient-to-r from-blue-700 to-indigo-700 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                            <svg className="w-5 h-5 mr-3 relative z-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                            </svg>
                            <span className="relative z-10">Ajouter une formation</span>
                        </button>
                    </div>
                </div>

                {/* Formation Cards Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                    {trainings.map(training => (
                        <div key={training.id} className="group relative bg-white rounded-2xl shadow-md hover:shadow-2xl border border-slate-100 overflow-hidden transition-all duration-500 hover:-translate-y-2">
                            {/* Status Badge */}
                            <div className="absolute top-4 right-4 z-10">
                                <span className="bg-emerald-100 text-emerald-700 text-xs font-semibold px-3 py-1 rounded-full">
                                    Active
                                </span>
                            </div>

                            {/* Card Header */}
                            <div className="relative h-32 bg-gradient-to-br from-blue-500 via-indigo-500 to-purple-600 p-6 overflow-hidden">
                                <div className="absolute inset-0 bg-black opacity-10"></div>
                                <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-5 rounded-full -mr-16 -mt-16"></div>
                                <div className="absolute bottom-0 left-0 w-24 h-24 bg-white opacity-5 rounded-full -ml-12 -mb-12"></div>
                                <h3 className="relative text-xl font-bold text-white leading-tight">
                                    {training.title}
                                </h3>
                            </div>

                            {/* Card Body */}
                            <div className="p-6">
                                <div className="space-y-4">
                                    {/* Theme */}
                                    <div className="flex items-start">
                                        <div className="bg-blue-50 p-2 rounded-lg mr-3">
                                            <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                                            </svg>
                                        </div>
                                        <div>
                                            <p className="text-xs text-slate-500 font-medium">Thème</p>
                                            <p className="text-sm text-slate-700 font-medium">{training.theme}</p>
                                        </div>
                                    </div>

                                    {/* Location */}
                                    <div className="flex items-start">
                                        <div className="bg-emerald-50 p-2 rounded-lg mr-3">
                                            <svg className="w-5 h-5 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                                            </svg>
                                        </div>
                                        <div>
                                            <p className="text-xs text-slate-500 font-medium">Lieu</p>
                                            <p className="text-sm text-slate-700 font-medium">{training.location}</p>
                                        </div>
                                    </div>

                                    {/* Dates */}
                                    <div className="flex items-start">
                                        <div className="bg-purple-50 p-2 rounded-lg mr-3">
                                            <svg className="w-5 h-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                            </svg>
                                        </div>
                                        <div>
                                            <p className="text-xs text-slate-500 font-medium">Période</p>
                                            <p className="text-sm text-slate-700 font-medium">
                                                {new Date(training.startDate).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                {' - '}
                                                {new Date(training.endDate).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short', year: 'numeric' })}
                                            </p>
                                        </div>
                                    </div>
                                </div>

                                {/* Action Button */}
                                <div className="mt-6">
                                    <button 
                                        onClick={() => handleAddParticipant(training)}
                                        className="w-full group bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-3 rounded-xl font-semibold hover:shadow-lg transform hover:-translate-y-0.5 transition-all duration-300 flex items-center justify-center"
                                    >
                                        <svg className="w-4 h-4 mr-2 group-hover:rotate-90 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                                        </svg>
                                        Gérer les participants
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Empty State */}
                {trainings.length === 0 && (
                    <div className="text-center py-24">
                        <div className="relative inline-block">
                            <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-indigo-400 rounded-full blur-3xl opacity-20 scale-150"></div>
                            <div className="relative bg-gradient-to-br from-slate-100 to-slate-50 rounded-full p-8 border border-slate-200">
                                <svg className="w-20 h-20 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                                </svg>
                            </div>
                        </div>
                        <h3 className="text-2xl font-bold text-slate-800 mt-8 mb-3">Aucune formation trouvée</h3>
                        <p className="text-slate-600 text-lg mb-8 max-w-md mx-auto">
                            Commencez par créer votre première formation pour organiser vos programmes de développement
                        </p>
                        <button
                            onClick={() => setShowModal(true)}
                            className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-8 py-4 rounded-xl font-semibold shadow-lg hover:shadow-xl transform hover:-translate-y-1 transition-all duration-300 inline-flex items-center"
                        >
                            <svg className="w-5 h-5 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                            </svg>
                            Créer votre première formation
                        </button>
                    </div>
                )}

                {/* Add Formation Modal */}
                {showModal && (
                    <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                        <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full transform transition-all duration-300 scale-100">
                            {/* Modal Header */}
                            <div className="relative bg-gradient-to-r from-blue-600 to-indigo-600 px-8 py-6 rounded-t-2xl">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-5 rounded-full -mr-16 -mt-16"></div>
                                <div className="absolute bottom-0 left-0 w-24 h-24 bg-white opacity-5 rounded-full -ml-12 -mb-12"></div>
                                <h2 className="relative text-2xl font-bold text-white">Nouvelle Formation</h2>
                                <p className="relative text-blue-100 text-sm mt-1">Créez une nouvelle formation</p>
                            </div>

                            {/* Modal Body */}
                            <div className="p-8">
                                <form onSubmit={handleSubmit} className="space-y-5">
                                    <div>
                                        <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                            <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                            </svg>
                                            Titre de la formation
                                        </label>
                                        <input
                                            type="text"
                                            name="title"
                                            value={formData.title}
                                            onChange={handleChange}
                                            required
                                            placeholder="Ex: Leadership et Management"
                                            className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                            <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                                            </svg>
                                            Thème
                                        </label>
                                        <input
                                            type="text"
                                            name="theme"
                                            value={formData.theme}
                                            onChange={handleChange}
                                            required
                                            placeholder="Ex: Développement personnel"
                                            className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                            <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                                            </svg>
                                            Lieu
                                        </label>
                                        <input
                                            type="text"
                                            name="location"
                                            value={formData.location}
                                            onChange={handleChange}
                                            required
                                            placeholder="Ex: Salle de conférence A"
                                            className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                        />
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                                <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                                </svg>
                                                Date de début
                                            </label>
                                            <input
                                                type="datetime-local"
                                                name="startDate"
                                                value={formData.startDate}
                                                onChange={handleChange}
                                                required
                                                className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                            />
                                        </div>

                                        <div>
                                            <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                                <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                                </svg>
                                                Date de fin
                                            </label>
                                            <input
                                                type="datetime-local"
                                                name="endDate"
                                                value={formData.endDate}
                                                onChange={handleChange}
                                                required
                                                className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                            />
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-semibold text-slate-700 mb-2 flex items-center">
                                            <svg className="w-4 h-4 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                                            </svg>
                                            Formateur
                                        </label>
                                        <select
                                            name="trainer"
                                            value={formData.trainer.id}
                                            onChange={handleChange}
                                            required
                                            className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                                        >
                                            <option value="">Sélectionner un formateur</option>
                                            {trainers.map(trainer => (
                                                <option key={trainer.id} value={trainer.id}>
                                                    {trainer.fullName}
                                                </option>
                                            ))}
                                        </select>
                                    </div>

                                    <div className="flex space-x-3 pt-6">
                                        <button
                                            type="submit"
                                            className="flex-1 bg-gradient-to-r from-blue-600 to-indigo-600 text-white py-3 rounded-xl font-semibold hover:shadow-lg transform hover:-translate-y-0.5 transition-all duration-200"
                                        >
                                            Créer la formation
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setShowModal(false)}
                                            className="flex-1 bg-slate-100 text-slate-700 py-3 rounded-xl font-semibold hover:bg-slate-200 transition-colors duration-200"
                                        >
                                            Annuler
                                        </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>
                )}

                {showParticipantModal && (
                    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                        <div className="bg-white rounded-xl p-8 max-w-2xl w-full mx-4 max-h-[80vh] overflow-y-auto">
                            <h2 className="text-2xl font-bold mb-6 text-gray-800">
                                Ajouter des participants à la formation
                            </h2>
                            <p className="text-gray-600 mb-4">
                                Formation: {selectedTraining?.title}
                            </p>
                            <form onSubmit={handleParticipantSubmit} className="space-y-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-3">
                                        Sélectionner les participants
                                    </label>
                                    <div className="max-h-60 overflow-y-auto border border-gray-200 rounded-lg p-3">
                                        {participants.map(participant => (
                                            <div key={participant.id} className="flex items-center py-2 hover:bg-gray-50">
                                                <input
                                                    type="checkbox"
                                                    id={`participant-${participant.id}`}
                                                    value={participant.id}
                                                    checked={selectedParticipants.includes(participant.id)}
                                                    onChange={() => handleParticipantChange(participant.id)}
                                                    className="w-4 h-4 text-marsa-blue border-gray-300 rounded focus:ring-marsa-blue focus:ring-2"
                                                />
                                                <label 
                                                    htmlFor={`participant-${participant.id}`}
                                                    className="ml-3 text-sm text-gray-700 cursor-pointer flex-1"
                                                >
                                                    {participant.fullName}
                                                </label>
                                            </div>
                                        ))}
                                        {participants.length === 0 && (
                                            <p className="text-gray-500 text-sm py-4 text-center">
                                                Aucun participant disponible
                                            </p>
                                        )}
                                    </div>
                                    {selectedParticipants.length > 0 && (
                                        <p className="text-sm text-gray-600 mt-2">
                                            {selectedParticipants.length} participant{selectedParticipants.length > 1 ? 's' : ''} sélectionné{selectedParticipants.length > 1 ? 's' : ''}
                                        </p>
                                    )}
                                </div>
                                <div className="flex space-x-3 pt-4">
                                    <button
                                        type="submit"
                                        disabled={selectedParticipants.length === 0}
                                        className="flex-1 bg-gradient-to-r from-marsa-blue to-blue-600 text-white py-2 rounded-lg font-medium hover:shadow-lg transition-shadow duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                                    >
                                        Ajouter ({selectedParticipants.length})
                                    </button>
                                    <button
                                        type="button"
                                        onClick={() => {
                                            setShowParticipantModal(false);
                                            setSelectedTraining(null);
                                            setSelectedParticipants([]);
                                        }}
                                        className="flex-1 bg-gray-200 text-gray-800 py-2 rounded-lg font-medium hover:bg-gray-300 transition-colors duration-200"
                                    >
                                        Annuler
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Formation;
